WITH filtered AS (SELECT *, ROUND(budget * 0.9, 2) AS adjusted_budget, CONCAT_WS('-', dept_name, location) AS dept_name_location_key, COALESCE(location, 'OTHER') AS location_filled FROM departments WHERE location IN ('Berlin', 'Bangkok')) SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.hire_date BETWEEN '2023-05-01' AND '2024-01-25')
